import { Injectable, Logger } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { Observable, Subject } from 'rxjs';
import { filter, map } from 'rxjs/operators';
import { PlatformEvent } from '../events/event.service';

@Injectable()
export class RealtimeService {
  private readonly logger = new Logger(RealtimeService.name);

  // Single global subject for all internal events.
  // In a multi-instance production environment, this would be backed by Redis Pub/Sub.
  private globalEventSubject = new Subject<{
    eventName: string;
    payload: PlatformEvent;
  }>();

  // Subscribe to ALL events fired by the application's EventEmitter
  @OnEvent('**')
  handleAllEvents(payload: any) {
    // The EventEmitter2 passes the event payload directly, but we don't necessarily get the event name here
    // unless we use the event context. NestJS @OnEvent doesn't inject the name into the args.
    // However, to keep it simple, if it's a PlatformEvent we just broadcast it.

    // Safety check - we only broadcast events that have a tenantId to avoid leaking system events
    if (payload && payload.tenantId) {
      this.globalEventSubject.next({
        // Extract type from payload if it exists, otherwise default
        eventName: payload.type || 'SYSTEM_EVENT',
        payload: payload as PlatformEvent,
      });
    }
  }

  // Allow a client to subscribe to events for their specific company
  subscribeToCompanyEvents(tenantId: string): Observable<{ data: any }> {
    this.logger.log(
      `Client subscribed to real-time events for tenant: ${tenantId}`,
    );

    return this.globalEventSubject.asObservable().pipe(
      // 1. Filter events so users only see their own company's data
      filter((event) => event.payload.tenantId === tenantId),
      // 2. Map to the SSE format required by NestJS (MessageEvent)
      map((event) => {
        // Map backend event structure to the frontend's expected RealtimeEvent structure
        const sseData = {
          id: event.payload.correlationId || `evt-${Date.now()}`,
          type: this.mapEventNameToFrontendType(event.eventName),
          payload: event.payload.payload, // The actual data
          timestamp: event.payload.timestamp || new Date().toISOString(),
        };

        return { data: sseData };
      }),
    );
  }

  private mapEventNameToFrontendType(eventName: string): string {
    if (eventName.includes('AiAlert') || eventName.includes('Anomaly')) {
      return 'AI_ALERT';
    }
    if (eventName.includes('Location') || eventName.includes('Telemetry')) {
      return 'TELEMETRY_UPDATED';
    }
    if (eventName.includes('Created') || eventName.includes('Updated')) {
      return 'ENTITY_UPDATED';
    }
    return 'SYSTEM_NOTIFICATION';
  }
}

import {
  Injectable,
  Logger,
  ServiceUnavailableException,
} from '@nestjs/common';

// ---------------------------------------------------------------------------
// Circuit Breaker with Retry Policy and Bulkhead
//
// Pattern: Netflix Hystrix / resilience4j design applied to Node.js.
//
// States:
//   CLOSED     — Normal operation. Failures increment counter.
//   OPEN       — Rejecting all calls. Entered after FAILURE_THRESHOLD failures.
//   HALF_OPEN  — Testing one probe call. Success → CLOSED, failure → OPEN.
//
// Retry Policy:
//   Exponential backoff with jitter. Max 3 retries by default.
//   Only retried on transient errors (not 4xx HTTP errors).
//
// Bulkhead:
//   Each integration has a separate concurrency limit.
//   Prevents one slow integration from exhausting the thread pool.
// ---------------------------------------------------------------------------

interface CircuitBreakerState {
  status: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
  failures: number;
  lastFailureAt: number;
  lastProbeAt?: number;
  concurrentCalls: number;
}

export interface CircuitBreakerOptions {
  failureThreshold?: number; // failures before OPEN (default: 5)
  resetTimeoutMs?: number; // time in OPEN before trying HALF_OPEN (default: 30s)
  maxConcurrent?: number; // bulkhead: max parallel calls (default: 10)
  retryCount?: number; // max retry attempts (default: 3)
  retryBaseDelayMs?: number; // base delay for exponential backoff (default: 200ms)
}

const DEFAULT_OPTIONS: Required<CircuitBreakerOptions> = {
  failureThreshold: 5,
  resetTimeoutMs: 30_000,
  maxConcurrent: 10,
  retryCount: 3,
  retryBaseDelayMs: 200,
};

@Injectable()
export class CircuitBreakerService {
  private readonly logger = new Logger(CircuitBreakerService.name);
  private readonly states = new Map<string, CircuitBreakerState>();
  private readonly options = new Map<string, Required<CircuitBreakerOptions>>();

  /** Configure a named circuit (call once at module init or on first use). */
  configure(name: string, opts: CircuitBreakerOptions): void {
    this.options.set(name, { ...DEFAULT_OPTIONS, ...opts });
  }

  /**
   * Execute `action` inside a circuit breaker + retry wrapper.
   * @param name    Unique identifier for this integration (e.g., 'LOCONAV', 'QUICKBOOKS')
   * @param action  The async operation to execute
   * @param opts    Per-call overrides (optional)
   */
  async execute<T>(
    name: string,
    action: () => Promise<T>,
    opts?: CircuitBreakerOptions,
  ): Promise<T> {
    const cfg: Required<CircuitBreakerOptions> = {
      ...DEFAULT_OPTIONS,
      ...(this.options.get(name) ?? {}),
      ...(opts ?? {}),
    };

    const state = this.getState(name);

    // Bulkhead check
    if (state.concurrentCalls >= cfg.maxConcurrent) {
      throw new ServiceUnavailableException(
        `[Bulkhead] Integration "${name}" at max concurrency (${cfg.maxConcurrent})`,
      );
    }

    // Circuit open check
    const now = Date.now();
    if (state.status === 'OPEN') {
      if (now - state.lastFailureAt < cfg.resetTimeoutMs) {
        throw new ServiceUnavailableException(
          `[CircuitBreaker] "${name}" is OPEN — pausing calls`,
        );
      }
      // Transition to HALF_OPEN for probe
      state.status = 'HALF_OPEN';
      state.lastProbeAt = now;
      this.logger.log(`[CircuitBreaker] "${name}" entering HALF_OPEN (probe)`);
    }

    state.concurrentCalls++;
    try {
      const result = await this.withRetry(name, action, cfg);
      this.onSuccess(name, state);
      return result;
    } catch (error) {
      this.onFailure(name, state, cfg);
      throw error;
    } finally {
      state.concurrentCalls = Math.max(0, state.concurrentCalls - 1);
    }
  }

  getStatus(name: string): {
    status: string;
    failures: number;
    concurrent: number;
  } {
    const s = this.states.get(name);
    return s
      ? {
          status: s.status,
          failures: s.failures,
          concurrent: s.concurrentCalls,
        }
      : { status: 'CLOSED', failures: 0, concurrent: 0 };
  }

  // ─────────────────────────────────────────────────────────────────────────
  private async withRetry<T>(
    name: string,
    action: () => Promise<T>,
    cfg: Required<CircuitBreakerOptions>,
  ): Promise<T> {
    let lastError: unknown;
    for (let attempt = 0; attempt <= cfg.retryCount; attempt++) {
      try {
        return await action();
      } catch (err: any) {
        lastError = err;
        // Don't retry client errors (4xx)
        if (err?.status >= 400 && err?.status < 500) throw err;
        if (attempt < cfg.retryCount) {
          // Exponential backoff with ±20% jitter
          const delay = cfg.retryBaseDelayMs * Math.pow(2, attempt);
          const jitter = delay * (0.8 + Math.random() * 0.4);
          this.logger.warn(
            `[Retry] "${name}" attempt ${attempt + 1}/${cfg.retryCount} failed — retrying in ${Math.round(jitter)}ms`,
          );
          await this.sleep(jitter);
        }
      }
    }
    throw lastError;
  }

  private onSuccess(name: string, state: CircuitBreakerState): void {
    if (state.status !== 'CLOSED') {
      this.logger.log(`[CircuitBreaker] "${name}" CLOSED (recovered)`);
    }
    state.status = 'CLOSED';
    state.failures = 0;
  }

  private onFailure(
    name: string,
    state: CircuitBreakerState,
    cfg: Required<CircuitBreakerOptions>,
  ): void {
    state.failures++;
    state.lastFailureAt = Date.now();

    if (state.status === 'HALF_OPEN') {
      state.status = 'OPEN';
      this.logger.error(
        `[CircuitBreaker] "${name}" probe failed — returning to OPEN`,
      );
      return;
    }

    if (state.failures >= cfg.failureThreshold) {
      state.status = 'OPEN';
      this.logger.error(
        `[CircuitBreaker] "${name}" TRIPPED (OPEN) after ${state.failures} failures`,
      );
    }
  }

  private getState(name: string): CircuitBreakerState {
    if (!this.states.has(name)) {
      this.states.set(name, {
        status: 'CLOSED',
        failures: 0,
        lastFailureAt: 0,
        concurrentCalls: 0,
      });
    }
    return this.states.get(name)!;
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Logger,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { EventStoreService } from '../digital-twin/event-store.service';

@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(GlobalExceptionFilter.name);

  constructor(private readonly eventStore: EventStoreService) {}

  async catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    let status = HttpStatus.INTERNAL_SERVER_ERROR;
    let message = 'An unexpected error occurred in PariLink Enterprise OS.';
    let errorCode = 'INTERNAL_ERROR';

    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const exceptionResponse: any = exception.getResponse();
      message = exceptionResponse?.message || exception.message;
      errorCode = exceptionResponse?.error || 'HTTP_EXCEPTION';
    } else if (exception instanceof Error) {
      message = exception.message;
    }

    const errorPayload = {
      statusCode: status,
      errorCode,
      message,
      timestamp: new Date().toISOString(),
      path: request.url,
      method: request.method,
      correlationId: request.headers['x-correlation-id'] || 'N/A',
    };

    // Log the error securely (observability + security audit)
    this.logger.error(
      `[${request.method}] ${request.url} - ${status} - ${message}`,
      (exception as Error)?.stack,
    );

    // Persist critical exceptions to the EventStore for audit trails
    if (status >= 500 || status === 403 || status === 401) {
      try {
        await this.eventStore.append({
          tenantId: 'SYSTEM',
          streamId: (request.headers['x-correlation-id'] as string) || 'system',
          streamType: 'SYSTEM_EXCEPTION',
          eventType: `HTTP_${status}_ERROR`,
          payload: errorPayload,
          userId: (request as any).user?.id || 'SYSTEM',
        });
      } catch (e) {
        this.logger.error('Failed to append exception to EventStore', e);
      }
    }

    // Mask internal 500 errors to prevent information leakage to the frontend
    if (status >= 500 && process.env.NODE_ENV === 'production') {
      errorPayload.message =
        'An internal system error occurred. Our operations team has been notified.';
    }

    response.status(status).json(errorPayload);
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CacheManagerService } from '../performance/cache-manager.service';

export interface RuleValidationContext {
  companyId: string;
  entityType: string; // e.g. 'TRIP', 'LOAD'
  entityId?: string;
  payload: any;
}

@Injectable()
export class BusinessRuleEngineService {
  private readonly logger = new Logger(BusinessRuleEngineService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly cache: CacheManagerService,
  ) {}

  /**
   * Executes configurable business rules dynamically.
   */
  async evaluateRules(ctx: RuleValidationContext): Promise<boolean> {
    this.logger.log(`Evaluating Business Rules for ${ctx.entityType}`);

    // Load active rules from DB/Cache (using mock static rules here for demonstration of ELOM without schema lock-in)
    // In a full implementation, rules are loaded from a 'BusinessRule' table.
    const activeRules = [
      { type: 'CAPACITY', target: 'LOAD', strict: true },
      { type: 'WORKING_HOURS', target: 'DRIVER', strict: true },
      { type: 'HAZMAT_COMPLIANCE', target: 'VEHICLE', strict: true },
      { type: 'COLD_CHAIN', target: 'TRAILER', strict: true },
    ];

    for (const rule of activeRules) {
      // 1. Capacity Rule
      if (
        rule.type === 'CAPACITY' &&
        ctx.payload.vehicleId &&
        ctx.payload.weight
      ) {
        const vehicle = await this.prisma.runAsSystem(async (tx) =>
          tx.vehicle.findFirst({
            where: { id: ctx.payload.vehicleId },
          }),
        );
        if (
          vehicle &&
          vehicle.capacityWeight &&
          ctx.payload.weight > vehicle.capacityWeight
        ) {
          if (rule.strict)
            throw new BadRequestException(
              `Rule violation: Load weight (${ctx.payload.weight}) exceeds vehicle capacity (${vehicle.capacityWeight}).`,
            );
        }
      }

      // 2. Working Hours (HOS Compliance)
      if (rule.type === 'WORKING_HOURS' && ctx.payload.driverId) {
        // Mock check against recent trips
        const recentTrips = await this.prisma.runAsSystem(async (tx) =>
          tx.trip.count({
            where: {
              driverId: ctx.payload.driverId,
              startDate: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) },
            },
          }),
        );
        if (recentTrips > 2) {
          if (rule.strict)
            throw new BadRequestException(
              `Rule violation: Driver ${ctx.payload.driverId} exceeds working hour limits (HOS).`,
            );
        }
      }

      // 3. HAZMAT Compliance
      if (
        rule.type === 'HAZMAT_COMPLIANCE' &&
        ctx.payload.isHazmat &&
        ctx.payload.vehicleId
      ) {
        const vehicle = await this.prisma.runAsSystem(async (tx) =>
          tx.vehicle.findFirst({
            where: { id: ctx.payload.vehicleId },
          }),
        );
        // Assume vehicle type defines hazmat readiness (mock validation)
        if (vehicle && vehicle.type !== 'HAZMAT_TRUCK') {
          if (rule.strict)
            throw new BadRequestException(
              `Rule violation: Vehicle ${vehicle.id} is not certified for Hazardous Materials (HAZMAT).`,
            );
        }
      }
    }

    return true;
  }
}

export interface ExecutionContext {
  workflowId: string;
  runId: string;
  attempt: number;
  tenantId: string;
  userId?: string;
  logger: any; // In production, this would be a Temporal Logger or Winston instance
}

/**
 * The standard interface that every executable service in PariLink must implement.
 * This guarantees a unified lifecycle for Workflow Tasks, AI Prompts, and Scheduled Jobs.
 */
export interface PlatformExecutable<TInput, TOutput> {
  /** Setup phase before execution (e.g. fetching necessary state) */
  initialize(context: ExecutionContext): Promise<void>;

  /** Schema and permission validation */
  validate(payload: TInput): Promise<boolean>;

  /** The core idempotent business logic */
  execute(payload: TInput): Promise<TOutput>;

  /** Saga compensation logic if the workflow fails downstream */
  compensate(payload: TInput, error: Error): Promise<void>;

  /** Teardown (closing temporary connections, etc) */
  cleanup(): Promise<void>;
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { CacheManagerService } from '../performance/cache-manager.service';

export interface ResourceAllocationRequest {
  companyId: string;
  resourceType:
    'VEHICLE' | 'DRIVER' | 'TRAILER' | 'DOCK' | 'WAREHOUSE' | 'YARD';
  resourceId: string;
  entityType: string;
  entityId: string;
  startTime: Date;
  endTime: Date;
}

@Injectable()
export class ResourceOrchestratorService {
  private readonly logger = new Logger(ResourceOrchestratorService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly cache: CacheManagerService,
  ) {}

  /**
   * Automatically orchestrates resource allocation.
   * Ensures NO conflicting allocations are permitted.
   */
  async allocateResource(req: ResourceAllocationRequest): Promise<boolean> {
    this.logger.log(
      `Allocating ${req.resourceType} ${req.resourceId} for ${req.entityType} ${req.entityId}`,
    );

    return this.prisma.runAsTenant(req.companyId, async (tx) => {
      // 1. Check for conflicting allocations in the time window
      // Using a generic allocation model or querying the specific resource type
      const hasConflict = await this.checkConflicts(tx, req);

      if (hasConflict) {
        throw new BadRequestException(
          `Resource ${req.resourceId} of type ${req.resourceType} has conflicting allocations in the requested time window.`,
        );
      }

      // 2. Register the allocation (we use a dedicated table or update the resource status)
      // Since schema changes are restricted, we can use a generic Redis-backed lock or
      // rely on the existing assignment patterns. For robust ELOM, we use an 'EventStore' or 'AuditLog'
      // to track allocations if a dedicated table isn't present, but ideally we update the resource state.

      if (req.resourceType === 'VEHICLE') {
        await tx.vehicle.update({
          where: { id: req.resourceId },
          data: { status: 'ALLOCATED' },
        });
      } else if (req.resourceType === 'DRIVER') {
        await tx.driver.update({
          where: { id: req.resourceId },
          data: { status: 'ALLOCATED' }, // assuming driver has status
        });
      }

      // Cache the allocation for fast conflict checks on high-throughput endpoints
      const cacheKey = `alloc:${req.companyId}:${req.resourceType}:${req.resourceId}`;
      await this.cache.set(
        cacheKey,
        req,
        Math.floor((req.endTime.getTime() - Date.now()) / 1000),
      );

      return true;
    });
  }

  private async checkConflicts(
    tx: any,
    req: ResourceAllocationRequest,
  ): Promise<boolean> {
    // Fast path: Check Redis cache
    const cacheKey = `alloc:${req.companyId}:${req.resourceType}:${req.resourceId}`;
    const cachedAlloc = (await this.cache.get(
      cacheKey,
    )) as ResourceAllocationRequest;

    if (cachedAlloc) {
      // Check time overlap
      const cStart = new Date(cachedAlloc.startTime);
      const cEnd = new Date(cachedAlloc.endTime);
      if (req.startTime < cEnd && req.endTime > cStart) {
        return true; // Conflict
      }
    }

    // Slow path: Check DB
    if (req.resourceType === 'VEHICLE') {
      const activeTrips = await tx.trip.count({
        where: {
          vehicleId: req.resourceId,
          status: { in: ['PLANNED', 'SCHEDULED', 'ALLOCATED', 'IN_PROGRESS'] },
          OR: [
            {
              startDate: { lte: req.endTime },
              endDate: { gte: req.startTime },
            },
            { endDate: null }, // Ongoing trip
          ],
        },
      });
      return activeTrips > 0;
    }

    if (req.resourceType === 'DRIVER') {
      const activeTrips = await tx.trip.count({
        where: {
          driverId: req.resourceId,
          status: { in: ['PLANNED', 'SCHEDULED', 'ALLOCATED', 'IN_PROGRESS'] },
          OR: [
            {
              startDate: { lte: req.endTime },
              endDate: { gte: req.startTime },
            },
            { endDate: null }, // Ongoing trip
          ],
        },
      });
      return activeTrips > 0;
    }

    // Expand logic for TRAILER, DOCK, YARD
    return false;
  }
}

import { BruteForceProtectionService } from './brute-force-protection.service';

describe('BruteForceProtectionService', () => {
  let service: BruteForceProtectionService;

  const mockRedisManager = {
    getClient: jest.fn().mockReturnValue(null),
  } as any;

  beforeEach(() => {
    service = new BruteForceProtectionService(mockRedisManager);
  });

  afterEach(async () => {
    await service.onModuleDestroy();
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('checkLoginAttempt', () => {
    it('should allow first attempt (no record)', async () => {
      const result = await service.checkLoginAttempt('user@test.com');
      expect(result.allowed).toBe(true);
      expect(result.remainingAttempts).toBe(5);
    });

    it('should allow attempt after recording fewer than 5 failures', async () => {
      await service.recordFailedAttempt('user@test.com');
      await service.recordFailedAttempt('user@test.com');
      const result = await service.checkLoginAttempt('user@test.com');
      expect(result.allowed).toBe(true);
      expect(result.remainingAttempts).toBe(3);
    });
  });

  describe('recordFailedAttempt', () => {
    it('should apply a SOFT LOCK after 5 failed attempts', async () => {
      for (let i = 0; i < 5; i++) {
        await service.recordFailedAttempt('user@lock.com');
      }
      const result = await service.checkLoginAttempt('user@lock.com');
      expect(result.allowed).toBe(false);
      expect(result.lockedUntil).toBeDefined();
      expect(result.permanentlyLocked).toBeUndefined();
    });

    it('should apply a PERMANENT LOCK after 10 failed attempts', async () => {
      for (let i = 0; i < 10; i++) {
        await service.recordFailedAttempt('user@hardlock.com');
      }
      const result = await service.checkLoginAttempt('user@hardlock.com');
      expect(result.allowed).toBe(false);
      expect(result.permanentlyLocked).toBe(true);
    });

    it('should be case-insensitive on email', async () => {
      await service.recordFailedAttempt('User@Test.com');
      await service.recordFailedAttempt('USER@TEST.COM');
      const result = await service.checkLoginAttempt('user@test.com');
      expect(result.remainingAttempts).toBe(3);
    });
  });

  describe('recordSuccessfulLogin', () => {
    it('should clear failed attempt record on successful login', async () => {
      await service.recordFailedAttempt('user@clear.com');
      await service.recordFailedAttempt('user@clear.com');
      await service.recordSuccessfulLogin('user@clear.com');

      const result = await service.checkLoginAttempt('user@clear.com');
      expect(result.allowed).toBe(true);
      expect(result.remainingAttempts).toBe(5);
    });
  });

  describe('adminUnlock', () => {
    it('should clear a permanent lock', async () => {
      for (let i = 0; i < 10; i++) {
        await service.recordFailedAttempt('user@admin.com');
      }
      await service.adminUnlock('user@admin.com');
      const result = await service.checkLoginAttempt('user@admin.com');
      expect(result.allowed).toBe(true);
    });
  });

  describe('isAccountLocked', () => {
    it('should return false for unknown user', async () => {
      expect(await service.isAccountLocked('unknown@user.com')).toBe(false);
    });

    it('should return true for permanently locked account', async () => {
      for (let i = 0; i < 10; i++) {
        await service.recordFailedAttempt('user@perm.com');
      }
      expect(await service.isAccountLocked('user@perm.com')).toBe(true);
    });

    it('should return true for soft-locked account within window', async () => {
      for (let i = 0; i < 5; i++) {
        await service.recordFailedAttempt('user@soft.com');
      }
      expect(await service.isAccountLocked('user@soft.com')).toBe(true);
    });
  });
});

import {
  Injectable,
  NestMiddleware,
  Logger,
  HttpStatus,
  OnModuleDestroy,
} from '@nestjs/common';
import { Request, Response, NextFunction } from 'express';
import { AuditService } from '../../audit/audit.service';
import { RedisManagerService } from '../../../common/redis/redis-manager.service';
import { Redis } from 'ioredis';

// ---------------------------------------------------------------------------
// API Gateway Rate Limiter — Enterprise (Redis-backed)
//
// Limits enforced (in order, highest priority first):
//   1. IP Block List — hard reject
//   2. Idempotency Key replay detection (TTL: 24h)
//   3. Burst Protection — max requests per second
//   4. Per-Tenant Quota — max requests per minute
// ---------------------------------------------------------------------------

// IP addresses that are blocked globally (loaded from env or DB at startup)
const BLOCKED_IPS = new Set<string>(
  (process.env.BLOCKED_IPS || '').split(',').filter(Boolean),
);

@Injectable()
export class ApiRateLimiterMiddleware
  implements NestMiddleware, OnModuleDestroy
{
  private readonly logger = new Logger(ApiRateLimiterMiddleware.name);

  // Defaults — overridden per-tenant by TenantConfig.apiRateLimit
  private readonly DEFAULT_RPM = 1000; // requests per minute
  private readonly BURST_RPS = 20; // requests per second burst cap
  private readonly WINDOW_S = 60; // 1 minute
  private readonly BURST_WINDOW_S = 1; // 1 second

  private readonly redis: Redis | null = null;
  private useRedis = false;

  // Memory fallbacks for dev environments without Redis
  private readonly fallbackMinuteBuckets = new Map<
    string,
    { count: number; windowStart: number }
  >();
  private readonly fallbackBurstBuckets = new Map<
    string,
    { count: number; windowStart: number }
  >();
  private readonly fallbackIdempotencyStore = new Map<string, number>();

  constructor(
    private readonly audit: AuditService,
    private readonly redisManager: RedisManagerService,
  ) {
    this.redis = this.redisManager.getClient();
    this.useRedis = true; // Handled by RedisManager
  }

  onModuleDestroy() {
    // Rely on RedisManagerService to close the pool
  }

  async use(req: Request, res: Response, next: NextFunction): Promise<void> {
    const ip = this.extractIp(req);
    const tenantId: string =
      (req as any).user?.companyId ??
      (req.headers['x-tenant-id'] as string) ??
      'anonymous';
    const idempotencyKey = req.headers['x-idempotency-key'] as
      string | undefined;

    // 1. IP Block List
    if (BLOCKED_IPS.has(ip)) {
      this.logger.warn(`[Gateway] Blocked IP attempted access: ${ip}`);
      res.status(HttpStatus.FORBIDDEN).json({ message: 'Access denied' });
      return;
    }

    // 2. Idempotency replay protection (POST/PUT/PATCH only)
    if (idempotencyKey && ['POST', 'PUT', 'PATCH'].includes(req.method)) {
      const replayKey = `idem:${tenantId}:${idempotencyKey}`;
      const isReplay = await this.checkIdempotency(replayKey);
      if (isReplay) {
        res.status(HttpStatus.CONFLICT).json({
          message: 'Duplicate request detected (idempotency key already used)',
          idempotencyKey,
        });
        return;
      }
    }

    // Determine limits
    let rpmLimit = this.getTenantLimit(req);
    let burstRps = this.BURST_RPS;

    const path = req.originalUrl || req.url;
    let category = 'general';
    if (path.includes('/api/v1/auth')) {
      rpmLimit = 50;
      burstRps = 10;
      category = 'auth';
    } else if (path.includes('/api/v1/webhooks')) {
      rpmLimit = 50;
      burstRps = 5;
      category = 'webhooks';
    } else if (path.includes('/api/v1/ai')) {
      rpmLimit = 200;
      burstRps = 30;
      category = 'ai';
    } else {
      // General limits for all other routes
      rpmLimit = 300;
      burstRps = 50;
    }

    // 3. Burst protection (per-second)
    const burstKey = `burst:${category}:${tenantId}:${ip}`;
    const burstAllowed = await this.checkLimit(
      burstKey,
      burstRps,
      this.BURST_WINDOW_S,
      this.fallbackBurstBuckets,
    );
    if (!burstAllowed.allowed) {
      res.setHeader('Retry-After', '1');
      res.status(HttpStatus.TOO_MANY_REQUESTS).json({
        message: 'Burst limit exceeded. Please reduce request rate.',
      });
      return;
    }

    // 4. Per-minute rate limit
    const minuteKey = `rpm:${category}:${tenantId}:${ip}`;
    const minuteLimit = await this.checkLimit(
      minuteKey,
      rpmLimit,
      this.WINDOW_S,
      this.fallbackMinuteBuckets,
    );

    res.setHeader('X-RateLimit-Limit', rpmLimit);
    res.setHeader('X-RateLimit-Remaining', Math.max(0, minuteLimit.remaining));
    res.setHeader('X-RateLimit-Reset', Math.floor(minuteLimit.resetAt / 1000));

    if (!minuteLimit.allowed) {
      const retryAfter = Math.ceil((minuteLimit.resetAt - Date.now()) / 1000);
      res.setHeader('Retry-After', retryAfter);
      this.audit
        .logEvent({
          action: 'RATE_LIMIT_EXCEEDED',
          entity: 'ApiGateway',
          entityId: tenantId,
          companyId:
            tenantId === 'anonymous' || tenantId === 'system'
              ? 'SYSTEM'
              : tenantId,
          source: 'API_GATEWAY',
          details: { ip, path: req.url, limit: rpmLimit },
        })
        .catch(() => {});
      res.status(HttpStatus.TOO_MANY_REQUESTS).json({
        message: 'Rate limit exceeded. Please wait before retrying.',
        retryAfter,
      });
      return;
    }

    next();
  }

  private getTenantLimit(req: Request): number {
    const headerLimit = req.headers['x-rate-limit-override'];
    if (headerLimit && !isNaN(Number(headerLimit))) return Number(headerLimit);
    return this.DEFAULT_RPM;
  }

  private async checkIdempotency(key: string): Promise<boolean> {
    if (this.useRedis && this.redis) {
      // SETNX returns 1 if key was set, 0 if it already existed
      const result = await this.redis.set(key, '1', 'EX', 86400, 'NX');
      return result !== 'OK';
    } else {
      const TTL_24H = Date.now() + 86_400_000;
      if (this.fallbackIdempotencyStore.has(key)) {
        if (this.fallbackIdempotencyStore.get(key)! > Date.now()) {
          return true;
        }
      }
      this.fallbackIdempotencyStore.set(key, TTL_24H);
      return false;
    }
  }

  private async checkLimit(
    key: string,
    limit: number,
    windowSeconds: number,
    fallbackMap: Map<string, { count: number; windowStart: number }>,
  ): Promise<{ allowed: boolean; remaining: number; resetAt: number }> {
    if (this.useRedis && this.redis) {
      // Redis INCR / EXPIRE pattern via pipeline for atomicity
      const current = Date.now();

      // Try to increment. If it doesn't exist, it's created at 0, then incremented to 1.
      const multi = this.redis.multi();
      multi.incr(key);
      multi.pttl(key);

      const results = await multi.exec();
      if (!results)
        return {
          allowed: true,
          remaining: limit - 1,
          resetAt: current + windowSeconds * 1000,
        };

      const count = results[0][1] as number;
      let ttl = results[1][1] as number;

      if (ttl === -1 || ttl === -2) {
        // Set expiry if missing or new
        await this.redis.expire(key, windowSeconds);
        ttl = windowSeconds * 1000;
      }

      return {
        allowed: count <= limit,
        remaining: limit - count,
        resetAt: current + ttl,
      };
    } else {
      // Fallback memory implementation
      const now = Date.now();
      const bucket = fallbackMap.get(key);

      if (!bucket || now - bucket.windowStart >= windowSeconds * 1000) {
        fallbackMap.set(key, { count: 1, windowStart: now });
        return {
          allowed: true,
          remaining: limit - 1,
          resetAt: now + windowSeconds * 1000,
        };
      }

      bucket.count++;
      const remaining = limit - bucket.count;
      const resetAt = bucket.windowStart + windowSeconds * 1000;

      return { allowed: bucket.count <= limit, remaining, resetAt };
    }
  }

  private extractIp(req: Request): string {
    return (
      (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ??
      req.socket.remoteAddress ??
      'unknown'
    );
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  UnauthorizedException,
} from '@nestjs/common';
import { Observable } from 'rxjs';

@Injectable()
export class TenantInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();

    // In PariLink, all authenticated requests MUST belong to a tenant (Company)
    // The JwtAuthGuard should have already populated req.user.companyId
    if (request.user && !request.user.companyId) {
      throw new UnauthorizedException('Tenant context missing from token');
    }

    // For APIs that require explicit tenant headers (e.g. Server-to-Server Integrations)
    if (!request.user) {
      const tenantHeader = request.headers['x-tenant-id'];
      if (!tenantHeader) {
        // We do not throw here because some endpoints (like login/public webhooks) are tenant-less
      } else {
        request['tenantId'] = tenantHeader;
      }
    } else {
      request['tenantId'] = request.user.companyId;
    }

    // Body mutation removed: Controllers correctly pass user.companyId to services directly.
    // Mutating request.body breaks ValidationPipe when forbidNonWhitelisted is true.

    return next.handle();
  }
}
